import pandas as pd


def _sig(val):
    """RTRIM(COALESCE(val, '')) -- legacy semantics: NULL/NaN -> '', trailing
    spaces stripped, leading spaces and case preserved."""
    if val is None or (isinstance(val, float) and pd.isna(val)):
        s = ''
    elif pd.isna(val):
        s = ''
    else:
        s = str(val)
    return s.rstrip(' ')


def _row_sig(city, tier):
    return _sig(city) + '|' + _sig(tier)


def run(inputs: dict) -> dict:
    dim = inputs["dim_member"].copy()
    stg = inputs["stg_member"].copy()

    # Ensure proper dtypes for columns we will touch.
    if 'eff_end_date' in dim.columns:
        dim['eff_end_date'] = pd.to_datetime(dim['eff_end_date'])
    if 'eff_start_date' in dim.columns:
        dim['eff_start_date'] = pd.to_datetime(dim['eff_start_date'])

    new_rows = []

    for _, s in stg.iterrows():
        mid = s['member_id']
        current_mask = (dim['member_id'] == mid) & (dim['is_current'] == 1)
        current_rows = dim[current_mask]

        if current_rows.empty:
            new_rows.append({
                'member_id': mid,
                'city': s['city'],
                'tier': s['tier'],
                'eff_start_date': s['update_date'],
                'eff_end_date': pd.NaT,
                'is_current': 1,
            })
        else:
            idx = current_rows.index[0]
            c = dim.loc[idx]
            if _row_sig(s['city'], s['tier']) != _row_sig(c['city'], c['tier']):
                dim.loc[idx, 'eff_end_date'] = s['update_date']
                dim.loc[idx, 'is_current'] = 0

                new_rows.append({
                    'member_id': mid,
                    'city': s['city'],
                    'tier': s['tier'],
                    'eff_start_date': s['update_date'],
                    'eff_end_date': pd.NaT,
                    'is_current': 1,
                })
            # else: no-op, keep c as-is

    if new_rows:
        new_df = pd.DataFrame(new_rows, columns=[
            'member_id', 'city', 'tier', 'eff_start_date', 'eff_end_date', 'is_current'
        ])
        new_df['eff_start_date'] = pd.to_datetime(new_df['eff_start_date'])
        new_df['eff_end_date'] = pd.to_datetime(new_df['eff_end_date'])
        new_df['member_id'] = new_df['member_id'].astype('int64')
        new_df['is_current'] = new_df['is_current'].astype('int64')

        result = pd.concat([dim, new_df], ignore_index=True)
    else:
        result = dim.reset_index(drop=True)

    result = result[['member_id', 'city', 'tier', 'eff_start_date', 'eff_end_date', 'is_current']]

    return {"dim_member_out": result}
